const BODY_ALIASES: Record<string, string> = {
  ASC: 'Ascendant', Rising: 'Ascendant', Midheaven: 'MC', 'True Node': 'North Node', 'Mean Node': 'North Node', Fortune: 'Part of Fortune',
};

function body(name: string): string {
  return BODY_ALIASES[name] || name;
}

/** Reading for a composite placement, or null when none is written. */
export function getCompositePlacementReading(planet: string, sign: string | null | undefined): string | null {
  if (!sign) return null;
  return PLACEMENT_READINGS[body(planet)]?.[sign] ?? null;
}

/** Reading for a composite aspect, or null when that pair has none written. */
export function getCompositeAspectReading(planet1: string, planet2: string, aspect: string): string | null {
  const entry = ASPECT_READINGS[[body(planet1), body(planet2)].sort().join('-')];
  if (!entry) return null;
  const a = aspect.toLowerCase();
  if (a === 'conjunction') return entry.fusion;
  if (a === 'trine' || a === 'sextile') return entry.flow;
  return entry.friction;
}
